<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/config.php';clevo_admin_actor($conn,clevo_current_user_id());clevo_privacy_schema($conn);
$ar=($_GET['lang']??'ar')!=='en';$t=static fn($a,$b)=>$ar?$a:$b;$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    foreach($_POST as $v)if(!is_string($v))throw new ClevoSecurityException('invalid_input',422);
    $input=['password'=>$_POST['password']??'','review_reference'=>$_POST['review_reference']??'','retention_reviewed'=>isset($_POST['retention_reviewed']),'external_cleanup_reviewed'=>isset($_POST['external_cleanup_reviewed'])];
    clevo_api_validate($input,clevo_api_contracts()['AccountErasureReview']);
    $id=filter_var($_POST['request_id']??'',FILTER_VALIDATE_INT);if(!$id)throw new ClevoSecurityException('invalid_id',422);
    clevo_rate_limit($conn,'privacy:admin-reauth',(string)clevo_current_user_id(),5,900);
    try{clevo_db_idempotent($conn,clevo_current_user_id(),'privacy.web.fulfill',$_POST['_key']??'',['request_id'=>$id]+$input,fn()=>clevo_privacy_fulfill($conn,clevo_current_user_id(),$id,$input));$notice=$t('تمت معالجة البيانات؛ راجع حالة تنظيف الملفات.','Data processing committed; inspect file-cleanup state.');}
    catch(ClevoSecurityException $e){$notice=$t('المعالجة محجوبة حتى مراجعة السياسة والالتزامات وإيقاف عمال الإرسال. السبب: ','Processing blocked pending policy, obligations and drained outbound workers. Reason: ').$e->reason;http_response_code($e->httpStatus);}
}
$page=clevo_api_integer('page',1,1,100000);$offset=($page-1)*25;
$rows=clevo_stmt($conn,'SELECT RequestID,UserID,State,RequestedAt,CompletedAt FROM account_deletion_requests ORDER BY RequestID DESC LIMIT 25 OFFSET ?','i',[$offset])->get_result()->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="<?= $ar?'ar':'en' ?>" dir="<?= $ar?'rtl':'ltr' ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CLEVO · Privacy</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="../assets/css/admin-management.css"></head><body><main class="container py-4"><a href="management.php">CLEVO Admin</a> · <a href="?lang=<?= $ar?'en':'ar' ?>">العربية / English</a><h1><?= $t('طلبات حذف الحساب','Account deletion requests') ?></h1>
<p><?= $t('يلزم اعتماد السياسة ومراجعة سجلات الاحتفاظ والمعالجات الخارجية والأصول القديمة، وإيقاف عمال الإرسال وانتظار انتهاء المهام المحجوزة. لا تُمحى السجلات المالية ولا تُلغى حجوزات تلقائياً هنا.','Requires approved policy, retention/external-processor/legacy-asset review, stopped outbound workers and drained leases. Financial journals are not erased and bookings are not automatically cancelled here.') ?></p>
<?php if($notice): ?><p role="status"><?= e($notice) ?></p><?php endif; ?>
<div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>User</th><th>State</th><th>UTC</th><th><?= $t('مراجعة ومعالجة','Review and process') ?></th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= (int)$r['RequestID'] ?></td><td><?= (int)$r['UserID'] ?></td><td><?= e($r['State']) ?></td><td><?= e($r['RequestedAt']) ?></td><td><?php if($r['State']==='requested'): ?><form method="POST"><?= csrf_input() ?><input type="hidden" name="_key" value="<?= bin2hex(random_bytes(24)) ?>"><input type="hidden" name="request_id" value="<?= (int)$r['RequestID'] ?>"><label><?= $t('مرجع المراجعة','Review reference') ?><input name="review_reference" maxlength="100" pattern="[A-Za-z0-9._/-]{4,100}" required></label><label><?= $t('كلمة مرور المسؤول','Admin password') ?><input type="password" name="password" autocomplete="current-password" required></label><label><input type="checkbox" name="retention_reviewed" required><?= $t('راجعت الاحتفاظ والالتزامات','Retention and obligations reviewed') ?></label><label><input type="checkbox" name="external_cleanup_reviewed" required><?= $t('اكتملت مراجعة المعالجات الخارجية والأصول القديمة','External processors and legacy assets reviewed') ?></label><button class="btn btn-danger"><?= $t('تنفيذ المحو بعد المراجعة','Erase after review') ?></button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><a href="?<?= e(http_build_query(['page'=>$page+1,'lang'=>$ar?'ar':'en'])) ?>"><?= $t('الصفحة التالية','Next page') ?></a></main><script>document.documentElement.dataset.theme=localStorage.getItem('global_theme')==='dark'?'dark':'light';</script></body></html>
